"A Model Context Protocol server gives a coding agent extra tools: files, the web, a browser, GitHub and the like. This only reaches the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — an agent used only with an API key cannot use one here.": "Ein Model-Context-Protocol-Server stellt einem Coding-Agenten zusätzliche Tools bereit: Dateien, das Web, einen Browser, GitHub und Ähnliches. Das erreicht nur die Agenten, die sich über ihr eigenes Befehlszeilentool in Termux anmelden (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) – ein Agent, der nur mit einem API-Schlüssel genutzt wird, kann hier keinen verwenden.",
"A Wear OS watch can be reached over its Bluetooth link to the phone, with no Wi-Fi. This phone then talks to the watch through its own ADB.": "Eine Wear-OS-Uhr lässt sich über ihre Bluetooth-Verbindung zum Telefon erreichen, ganz ohne Wi-Fi. Dieses Telefon spricht dann über sein eigenes ADB mit der Uhr.",
