"Another folder": "Anderer Ordner",
"Another theme": "Anderes Design",
"Anthropic does not allow other apps to sign in with a Claude Pro or Max account. Claude Code, Anthropic's own tool, can: it runs in Termux, and the Terminal chats through it. With an API key saved, Claude Code uses the key instead.": "Anthropic erlaubt anderen Apps nicht, sich mit einem Konto für Claude Pro oder Max anzumelden. Claude Code, das eigene Tool von Anthropic, kann das: Es läuft in Termux, und das Terminal chattet darüber. Ist ein API-Schlüssel gespeichert, verwendet Claude Code stattdessen den Schlüssel.",
"Any screen density": "Beliebige Bildschirmdichte",
"Anyone who has the password can open it. If it is lost, the files can not be recovered.": "Jeder, der das Passwort hat, kann das Archiv öffnen. Geht das Passwort verloren, können die Dateien nicht wiederhergestellt werden.",
"AnythingLLM": "AnythingLLM",
"AnythingLLM runs on a computer or a server (Desktop or Docker). Enter its address (like http://192.168.1.20:3001/api/v1/openai) and an API key from AnythingLLM, Settings, Developer API. Each workspace shows up as a model.": "AnythingLLM läuft auf einem Computer oder Server (Desktop oder Docker). Geben Sie seine Adresse (etwa http://192.168.1.20:3001/api/v1/openai) und einen API-Schlüssel aus AnythingLLM ein (Einstellungen, Developer API). Jeder Arbeitsbereich erscheint als Modell.",
