"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store ist ein quelloffener Play-Store-Client. Die automatische Erkennung der Play-Version ist als Nächstes geplant (sie erfordert eine anonyme Play-Authentifizierung); vorerst leitet dies jede App zu ihrer Store-Seite weiter und öffnet Aurora Store, sofern installiert.",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: installiert · Play Store: installiert. Tippen Sie unten auf eine App, um ihre Store-Seite zu öffnen.",
