"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro oder Max und eine Anmeldung mit einem Google-Konto dürfen nur in den eigenen Apps der Anbieter verwendet werden: Anthropic und Google erlauben anderen Apps nicht, diese Anmeldungen zu nutzen. Deshalb meldet das Terminal Sie über die offiziellen Befehlszeilentools an, die in Termux laufen und dort die Website-Anmeldung des Anbieters öffnen:",
