"Freeze cached apps": "Zwischengespeicherte Apps einfrieren",
"Freeze, debloat, install, back up and inspect every app on your phone, straight from the phone: through ADB, Wireless Debugging, Shizuku or Root. No computer, no account, no ads.": "Apps auf Ihrem Telefon einfrieren, Bloatware entfernen, installieren, sichern und untersuchen – direkt auf dem Telefon: über ADB, Kabelloses Debugging, Shizuku oder Root. Ohne Computer, ohne Konto, ohne Werbung.",
"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "Aus dem Dateimanager: Installation über ein privilegiertes Backend, bei ausgeschalteten Signaturprüfungen dieser App. Android prüft Signaturen weiterhin selbst: Ein APK, dessen Signatur es nicht verifizieren kann, wird mit dem Schlüssel dieser App signiert und installiert; eine von jemand anderem signierte App lässt sich erst nach dem Deinstallieren ersetzen (Sie werden vorher gefragt).",
