"Hands the queued files to Android's Bluetooth sharing, which asks which paired device gets them. Most watches, Wear OS included, cannot receive files this way: for a Wear OS watch use the Bluetooth link under Add device and send over ADB instead.": "Übergibt die Dateien in der Warteschlange an die Bluetooth-Freigabe von Android, die fragt, welches gekoppelte Gerät sie erhält. Die meisten Uhren, auch Wear OS, können Dateien so nicht empfangen: Nutzen Sie bei einer Wear-OS-Uhr stattdessen die Bluetooth-Verbindung unter „Gerät hinzufügen“ und senden Sie über ADB.",
