"It could not be saved": "Konnte nicht gespeichert werden",
"It did not finish": "Der Vorgang wurde nicht abgeschlossen",
"It did not work": "Es hat nicht funktioniert",
"It finishes installing itself the first time it opens.": "Beim ersten Öffnen schließt es die Installation selbst ab.",
"It goes back to the version that came with the phone. An older version often cannot use the data of a newer one, so it may lose its data.": "Sie geht auf die Version zurück, die mit dem Telefon geliefert wurde. Eine ältere Version kann die Daten einer neueren oft nicht nutzen, deshalb gehen ihre Daten möglicherweise verloren.",
"It has no Android build, so it goes into a Debian container inside Termux (several minutes, a few hundred MB). Already installed steps are skipped quickly.": "Für dieses Tool gibt es keinen Android-Build, daher wird es in einem Debian-Container innerhalb von Termux installiert (mehrere Minuten, einige hundert MB). Bereits erledigte Schritte werden schnell übersprungen.",
"It is not set any more": "Die Einstellung ist nicht mehr gesetzt",
"It is removed for the device's user. A system app can be put back with Reinstall.": "Sie wird für den Benutzer des Geräts entfernt. Eine System-App lässt sich mit „Neu installieren“ zurückholen.",
"It is removed for you. A system app stays on the phone and can be brought back with Reinstall.": "Sie wird für Sie entfernt. Eine System-App bleibt auf dem Telefon und lässt sich mit „Neu installieren“ zurückholen.",
"It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Es wird zuerst unverändert versucht; lehnt Android es ab, wird eine mit dem Schlüssel dieser App signierte Kopie installiert.",
"Its settings, accounts and files on the device are deleted.": "Ihre Einstellungen, Konten und Dateien auf dem Gerät werden gelöscht.",
"Its settings, accounts, saved games and the files in its own storage are deleted. This cannot be undone.": "Ihre Einstellungen, Konten, Spielstände und die Dateien in ihrem eigenen Speicher werden gelöscht. Dies kann nicht rückgängig gemacht werden.",
"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid page": "IzzyOnDroid-Seite",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan führt KI-Modelle kostenlos auf Ihrem Computer aus. Am Computer: Jan, Einstellungen, Local API Server: Setzen Sie den Host auf 0.0.0.0 und starten Sie den Server, geben Sie dann hier die Adresse des Computers ein (etwa http://192.168.1.20:1337/v1). Eine Android-Version von Jan gibt es nicht.",
