"Shows what changes, line by line, with Apply, Skip and Always allow in this chat.": "Zeigt zeilenweise, was sich ändert, mit „Anwenden“, „Überspringen“ und „In diesem Chat immer zulassen“.",
"Sideloaded apps are matched to their source through your sources, your imported Obtainium list, the Obtainium community catalog, IzzyOnDroid and F-Droid. Every download is checked to be the same app, a newer version and signed with the same key before installing through ADB, Shizuku or Root. Play Store apps keep updating through the Play Store.": "Per Sideload installierte Apps werden ihrer Quelle zugeordnet – über Ihre Quellen, Ihre importierte Obtainium-Liste, den Obtainium-Community-Katalog, IzzyOnDroid und F-Droid. Jeder Download wird vor der Installation über ADB, Shizuku oder Root darauf geprüft, dass er dieselbe App, eine neuere Version und mit demselben Schlüssel signiert ist. Play-Store-Apps werden weiterhin über den Play Store aktualisiert.",
"Sideloaded apps with no known source. Set a GitHub, Codeberg or F-Droid link to check them.": "Per Sideload installierte Apps ohne bekannte Quelle. Legen Sie einen GitHub-, Codeberg- oder F-Droid-Link fest, um sie zu prüfen.",
