"That is not a valid pattern, so it is searched as plain text.": "Das ist kein gültiges Muster, daher wird als einfacher Text gesucht.",
"That is not a valid profile": "Das ist kein gültiges Profil",
"That is the density now": "Das ist bereits die aktuelle Dichte",
"That name is already used here": "Dieser Name wird hier bereits verwendet",
"That name is not allowed": "Dieser Name ist nicht zulässig",
"That one would stop the adb this app runs on, so it is not sent.": "Dieser Befehl würde das adb beenden, auf dem diese App läuft, und wird deshalb nicht gesendet.",
"That part of the guide is not there.": "Dieser Teil der Anleitung ist nicht vorhanden.",
"That password did not work. Try again.": "Dieses Passwort hat nicht funktioniert. Bitte erneut versuchen.",
"That pattern could freeze the list (a repeat inside a repeat, or very long), so it is searched as plain text.": "Dieses Muster könnte die Liste zum Hängen bringen (eine Wiederholung innerhalb einer Wiederholung oder sehr lang), daher wird als einfacher Text gesucht.",
"That port is used by this phone's own ADB. Use another, like 4444.": "Dieser Port wird vom eigenen ADB dieses Telefons verwendet. Verwenden Sie einen anderen, z. B. 4444.",
"The # button switches to commands.": "Die Schaltfläche # wechselt zu Befehlen.",
"The $ button switches to commands.": "Die Schaltfläche $ wechselt zu Befehlen.",
"The ADB key and the APK-signing key are created on this phone and never leave it.": "Der ADB-Schlüssel und der APK-Signierschlüssel werden auf diesem Telefon erstellt und verlassen es nie.",
"The Action Button": "Die Aktionsschaltfläche",
"The Bluetooth link could not be set up.": "Die Bluetooth-Verbindung konnte nicht eingerichtet werden.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "Die Schaltfläche MCP öffnet ein Menü, um einem Agenten über das Model Context Protocol zusätzliche Tools zu geben (Dateien, das Web, einen Browser, GitHub...). Wählen Sie eine Voreinstellung oder schreiben Sie eine eigene: einen Namen, einen lokalen Befehl oder eine Remote-Adresse und gegebenenfalls einen Schlüssel oder Header. Wählen Sie, zu welchen Agenten es hinzugefügt wird – derselbe Server kann in zwei oder mehr gleichzeitig gelangen, da jeder Agent ihn in seiner eigenen Datei speichert.",
"The PDF could not be shown.": "Das PDF konnte nicht angezeigt werden.",
"The Rish shell ended. Tap Rish mode to open a new one.": "Die Rish-Shell wurde beendet. Tippen Sie auf „Rish-Modus“, um eine neue zu öffnen.",
"The Rish shell is no longer running.": "Die Rish-Shell läuft nicht mehr.",
"The Terminal needs the app (it is not available in a plain browser)": "Das Terminal benötigt die App (in einem normalen Browser ist es nicht verfügbar)",
"The UAD-NG list has not been downloaded yet.": "Die UAD-NG-Liste wurde noch nicht heruntergeladen.",
"The account has no credit left, or a spending limit was reached.": "Das Konto hat kein Guthaben mehr, oder ein Ausgabenlimit wurde erreicht.",
"The agent is still working: STOP it first": "Der Agent arbeitet noch: Halten Sie ihn zuerst mit STOP an",
"The agent pauses after this many steps.": "Der Agent pausiert nach dieser Anzahl von Schritten.",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "Die App ist kostenlos und bleibt es auch. Wenn sie Ihnen Zeit gespart hat, hilft mir ein Kaffee, sie weiter zu verbessern. Völlig freiwillig – und vielen Dank!",
"The archive file is rewritten without this file.": "Die Archivdatei wird ohne diese Datei neu geschrieben.",
"The archive file is rewritten without this folder and everything in it.": "Die Archivdatei wird ohne diesen Ordner und seinen gesamten Inhalt neu geschrieben.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "Das Archiv wird nur gelöscht, wenn alle seine Dateien entpackt wurden und keine übersprungen wurde.",
"The archive job failed": "Der Archivvorgang ist fehlgeschlagen",
