"The device restarts and the connection drops for a moment.": "Das Gerät startet neu und die Verbindung bricht kurz ab.",
"The device restarts into recovery mode.": "Das Gerät startet im Recovery-Modus neu.",
"The device restarts into the bootloader.": "Das Gerät startet im Bootloader neu.",
"The device turns off. It has to be started by hand.": "Das Gerät schaltet sich aus. Es muss von Hand wieder gestartet werden.",
"The device's own log.": "Das eigene Protokoll des Geräts.",
"The device's system, secure and global settings. A wrong value can make a device misbehave: change one at a time.": "Die Einstellungen System, Secure und Global des Geräts. Ein falscher Wert kann zu Fehlfunktionen führen: Ändern Sie jeweils nur eine.",
"The edit could not start": "Die Bearbeitung konnte nicht gestartet werden",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "Die Zusatztasten funktionieren wie bei Termux: ESC löscht die Zeile, TAB vervollständigt einen Dateinamen, CTRL-C stoppt, was gerade läuft, die Pfeile blättern durch frühere Befehle und bewegen den Cursor, HOME und END springen in der Zeile, und | / - ~ sind vorhanden, weil Telefontastaturen sie verbergen.",
"The extraction could not start": "Das Entpacken konnte nicht gestartet werden",
"The file": "Die Datei",
"The file chooser needs the app build": "Die Dateiauswahl benötigt die App-Version",
"The file is removed from this phone's storage, not just from the list. An Undo bar stays for a few seconds, and the file only goes for good once that bar is gone.": "Die Datei wird aus dem Speicher dieses Telefons entfernt, nicht nur aus der Liste. Einige Sekunden lang bleibt eine Rückgängig-Leiste sichtbar; erst wenn sie verschwunden ist, ist die Datei endgültig weg.",
"The fingerprint is shown in the app build": "Der Fingerabdruck wird im App-Build angezeigt",
