"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Diese App kann den Speicher nicht lesen. Erteile den Zugriff auf alle Dateien oder wähle eine Schriftdatei von Hand aus (dafür ist kein Zugriff nötig).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Diese App verlangt keinen bestimmten Touchscreen, keine bestimmte Tastatur und keine bestimmte Navigation (sie hat keinen uses-configuration-Eintrag) und läuft daher mit dem, was dieses Telefon hat.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Diese App führt keine Hardware- oder Softwarefunktionen auf, die sie benötigt (keine uses-feature-Einträge).",
"This app has no activities.": "Diese App hat keine Activities.",
"This app may not run commands in Termux yet.": "Diese App darf in Termux möglicherweise noch keine Befehle ausführen.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Diese App hat jetzt einen eigenen privaten ADB-Schlüssel. Tippen Sie auf die Modusanzeige für Details.",
"This app's own shell - no root, ADB or package manager.": "Die eigene Shell dieser App – ohne Root, ADB oder Paketmanager.",
"This app's own user and group id": "Die eigene Benutzer- und Gruppen-ID dieser App",
"This app’s key · 2048-bit RSA · in secure hardware": "Schlüssel dieser App · 2048-Bit-RSA · in sicherer Hardware",
"This app’s key · 2048-bit RSA · in the Android Keystore": "Schlüssel dieser App · 2048-Bit-RSA · im Android Keystore",
"This archive is view-only": "Dieses Archiv ist schreibgeschützt",
