"This can cut the ADB connection this app uses, so you may not be able to change it back from here.": "Dies kann die ADB-Verbindung trennen, die diese App nutzt, sodass Sie es von hier aus möglicherweise nicht zurückändern können.",
"This can lock you out of parts of the phone (the screen, the keyboard or accessibility).": "Dadurch können Sie sich aus Teilen des Telefons aussperren (Bildschirm, Tastatur oder Bedienungshilfen).",
