"This is already what the phone uses.": "Das verwendet das Telefon bereits.",
"This is not a text file. Use View, or Open with…": "Das ist keine Textdatei. Verwenden Sie „Ansehen“ oder „Öffnen mit…“.",
"This is the top of this storage": "Dies ist die oberste Ebene dieses Speichers",
"This looks like a binary file. Pull it to this phone instead.": "Das sieht nach einer Binärdatei aus. Holen Sie sie stattdessen auf dieses Telefon.",
"This needs the app build.": "Dies erfordert den App-Build.",
"This only works with the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); an agent used only with an API key cannot use one here.": "Das funktioniert nur mit den Agenten, die sich über ihr eigenes Befehlszeilentool in Termux anmelden (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); ein Agent, der nur mit einem API-Schlüssel genutzt wird, kann hier keinen verwenden.",
"This package carries data files that live outside the APK. Right after the install succeeds they are copied into place.": "Dieses Paket enthält Datendateien, die außerhalb des APK liegen. Direkt nach der erfolgreichen Installation werden sie an ihren Platz kopiert.",
"This page is running without the app, so there is no phone to read the settings from.": "Diese Seite läuft ohne die App, daher gibt es kein Telefon, von dem Einstellungen gelesen werden können.",
