"Turn a tab off to take it out of the tab bar and use the arrows to put the tabs in the order you like. Application Manager and About always stay where they are.": "Schalten Sie einen Tab aus, um ihn aus der Tab-Leiste zu entfernen, und ordnen Sie die Tabs mit den Pfeilen nach Wunsch an. „App-Manager“ und „Info“ bleiben immer an ihrer Stelle.",
